import random

suits = ['♠', '♥', '♦', '♣']
ranks = [ '2', '3', '4', '5', '6', '7', '8', '9', '10', 'A', 'J', 'Q', 'K']
cards = []

face_cards = ['J', 'Q', 'K']

for suit in suits:
    for rank in ranks:
        cards.append((suit, rank))

random.shuffle(cards) # TODO remember: random.shuffle function, it is very useful.
                        #TODO remember: random.choice returns a single random element from an non-empty sequence like a list or a tuple

player_cards = random.choices(cards, k=2)  #Similarly, choices enables you to choose multiple elements from the list by just specifying the quantity of elements by a variable k.
dealer_cards = random.choices(cards, k=2)

player_score = 0;
dealer_score = 0;

print(f"Player: {player_cards}")
print(f"Dealer: {dealer_cards[0]}")


if any(item in player_cards for item in face_cards ):
    player_score += 10

if (10 < player_score < 21) and any('A' in player_card for player_card in player_cards):
    player_score

if any(face_card in dealer_cards for face_card in face_cards):
    dealer_score += 10

tuple_list = [('A', 1), ('B', 2)]

print(any('A' in item for item in tuple_list ))